starting_files.entry.ips:
asset Conditional {
  size 32x32
  input f32 probability=0.5
  output point center
  draw { rect(0,0,32,32,#101820) if (probability) { rect(8,8,16,16,#44ff44) } center={16,16} }
}

asset Typo {
  size 32x32
  output point center
  draw { rect(0,0,32,32,#101820) rect(x=8,y=8,w=16,h=16,colour=#55bbff) center={16,16} }
}

asset Scope {
  size 32x32
  input color tint=#55bbff
  output point center
  draw { rect(0,0,32,32,#101820) paint() center={16,16} }
  paint() { rect(8,8,16,16,tint) }
}

asset Recursive {
  size 32x32
  output point measured
  draw { rect(0,0,32,32,#101820) rect(2,2,height(4),4,#ff4444) measured={height(4),4} }
  height(n:i32)->i32 { if (n<=0) { return 0 } return 1+height(n-1) }
}

asset RampType {
  size 32x32
  palette levels=[0,1]
  output point midpoint
  draw { rect(0,0,32,32,#101820) t=ramp(levels,0.5) midpoint={t,t} pixel(8,8,rgb(int(t*255.0),int(t*255.0),int(t*255.0))) }
}

import tile from "part.ips"
asset ListRead {
  size 32x32
  output point anchor
  draw { rect(0,0,32,32,#101820) tile.draw(7,0,0,at={8,8}) anchor=tile.outputs.marks+{8,8} }
}

